func testEmpresaFilialToManySetOpEmfChecklists(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a EmpresaFilial
	var b, c, d, e Checklist

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, empresaFilialDBTypes, false, strmangle.SetComplement(empresaFilialPrimaryKeyColumns, empresaFilialColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Checklist{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, checklistDBTypes, false, strmangle.SetComplement(checklistPrimaryKeyColumns, checklistColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetEmfChecklists(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EmfChecklists().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetEmfChecklists(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EmfChecklists().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EmfID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EmfID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.EmfID, d.EmfID) {
		t.Error("foreign key was wrong value", a.EmfID, d.EmfID)
	}
	if !queries.Equal(a.EmfID, e.EmfID) {
		t.Error("foreign key was wrong value", a.EmfID, e.EmfID)
	}

	if b.R.Emf != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Emf != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Emf != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Emf != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.EmfChecklists[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.EmfChecklists[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testEmpresaFilialToManyRemoveOpEmfChecklists(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a EmpresaFilial
	var b, c, d, e Checklist

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, empresaFilialDBTypes, false, strmangle.SetComplement(empresaFilialPrimaryKeyColumns, empresaFilialColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Checklist{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, checklistDBTypes, false, strmangle.SetComplement(checklistPrimaryKeyColumns, checklistColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddEmfChecklists(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EmfChecklists().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveEmfChecklists(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EmfChecklists().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EmfID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EmfID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Emf != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Emf != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Emf != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Emf != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.EmfChecklists) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.EmfChecklists[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.EmfChecklists[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

